CREATE DATABASE IF NOT EXISTS vnet CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE vnet;
CREATE TABLE IF NOT EXISTS networks (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(128) NOT NULL, topology VARCHAR(64) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS nodes (id BIGINT PRIMARY KEY AUTO_INCREMENT, network_id BIGINT NOT NULL, name VARCHAR(128) NOT NULL, kind VARCHAR(32) NOT NULL, ipv4 VARCHAR(15), FOREIGN KEY(network_id) REFERENCES networks(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS interfaces (id BIGINT PRIMARY KEY AUTO_INCREMENT, node_id BIGINT NOT NULL, name VARCHAR(64) NOT NULL, mac VARCHAR(17), ipv4 VARCHAR(15), FOREIGN KEY(node_id) REFERENCES nodes(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS routes (id BIGINT PRIMARY KEY AUTO_INCREMENT, node_id BIGINT NOT NULL, network VARCHAR(15) NOT NULL, prefix TINYINT UNSIGNED NOT NULL, next_hop VARCHAR(15), metric INT UNSIGNED DEFAULT 1, FOREIGN KEY(node_id) REFERENCES nodes(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS packets (id BIGINT PRIMARY KEY AUTO_INCREMENT, network_id BIGINT, protocol VARCHAR(32), source_ip VARCHAR(45), destination_ip VARCHAR(45), payload_size INT UNSIGNED, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS algorithms (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(128) UNIQUE NOT NULL, category VARCHAR(64) NOT NULL, version VARCHAR(32), license VARCHAR(128), provenance TEXT);
CREATE TABLE IF NOT EXISTS neural_networks (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(128) UNIQUE NOT NULL, input_size INT UNSIGNED NOT NULL, output_size INT UNSIGNED NOT NULL, learning_rate DOUBLE DEFAULT 0.001);
CREATE TABLE IF NOT EXISTS neural_weights (id BIGINT PRIMARY KEY AUTO_INCREMENT, network_id BIGINT NOT NULL, layer_index INT UNSIGNED NOT NULL, node_index INT UNSIGNED NOT NULL, weight_index INT UNSIGNED NOT NULL, weight DOUBLE NOT NULL, FOREIGN KEY(network_id) REFERENCES neural_networks(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS system_settings (setting_key VARCHAR(128) PRIMARY KEY, setting_value TEXT NOT NULL);
